<style>
  :root { --field: #f6efe1; }
  @media (prefers-color-scheme: dark) { :root { --field: #130e09; } }
  html, body { height: 100%; margin: 0; }
  body { background: var(--field); display: grid; place-items: center; }

  .bit { width: 96px; height: 96px; outline: none; cursor: default; -webkit-tap-highlight-color: transparent; }
  .bit svg { display: block; width: 100%; height: 100%; overflow: visible;
             transition: transform .35s cubic-bezier(.3,.7,.4,1); }

  /* at rest the mark is the favicon's; on hover it turns and bores in. The turn is the facets'
     shades handed one facet along per beat, which on a faceted bit reads as rotation. */
  .bit:hover svg, .bit:focus-visible svg, .bit:active svg { transform: translateY(6px); }
  .bit:hover .spin, .bit:focus-visible .spin, .bit:active .spin { animation: chatter .09s linear infinite; }
  .bit:hover .r1, .bit:focus-visible .r1, .bit:active .r1 { animation: turn5 .5s linear infinite; }
  .bit:hover .r2, .bit:focus-visible .r2, .bit:active .r2 { animation: turn3 .3s linear infinite; }
  .bit:hover .tip, .bit:focus-visible .tip, .bit:active .tip { animation: glint .3s linear infinite; }

  .r1:nth-child(1) { animation-delay: 0s !important; }
  .r1:nth-child(2) { animation-delay: -.1s !important; }
  .r1:nth-child(3) { animation-delay: -.2s !important; }
  .r1:nth-child(4) { animation-delay: -.3s !important; }
  .r1:nth-child(5) { animation-delay: -.4s !important; }
  .r2:nth-child(6) { animation-delay: 0s !important; }
  .r2:nth-child(7) { animation-delay: -.1s !important; }
  .r2:nth-child(8) { animation-delay: -.2s !important; }

  @keyframes turn5 {
    0%   { fill: #cd964e; } 20% { fill: #c88d3e; } 40% { fill: #c4842f; }
    60%  { fill: #b2782b; } 80% { fill: #a36e27; } 100% { fill: #cd964e; }
  }
  @keyframes turn3 {
    0% { fill: #a0593f; } 33.3% { fill: #96472a; } 66.6% { fill: #843e25; } 100% { fill: #a0593f; }
  }
  @keyframes glint { 0%, 100% { fill: #5c3a44; } 50% { fill: #6e4652; } }
  @keyframes chatter {
    0%, 100% { transform: translate(0, 0); }
    25% { transform: translate(-.35px, .25px); }
    75% { transform: translate(.35px, -.25px); }
  }

  @media (prefers-reduced-motion: reduce) {
    .bit svg { transition: none; }
    .bit:hover svg, .bit:focus-visible svg, .bit:active svg { transform: none; }
    .bit .spin, .bit .r1, .bit .r2, .bit .tip { animation: none !important; }
  }
</style>
</head>
